{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C14"],
      "claim": "Brigatinib, a kinase inhibitor with a piperazine/pyrimidine/phosphine oxide scaffold closely related to the query, has an approximate absolute oral bioavailability of 46% in healthy volunteers, directly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "The high-transfer piperazine/pyrimidine analogue (recorded as GSK1322322) achieved 77% absolute oral bioavailability in healthy volunteers in the fed state, showing that this scaffold class can be well absorbed despite high polarity and ionization.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "The same high-transfer analogue achieved 57% absolute oral bioavailability in the fasted state, still well above the 20% threshold, indicating robust absorption even without food.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Linezolid, a polar small molecule with multiple H-bond acceptors, has near-100% oral bioavailability, demonstrating that high TPSA/HBA does not preclude high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Encainide, a basic amine-containing drug, has 76 ± 17% oral bioavailability in patients with cirrhosis, supporting high F for ionizable amines despite disease-related changes.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Paliperidone extended-release, a weak-base drug with a piperidine and heteroaromatic system, has 28% absolute oral bioavailability, still above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Rifapentine, a large, high-MW, complex drug, has 70% oral bioavailability in humans, showing that size and complexity do not necessarily cause low F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Predicted high (F ≥ 20%). Multiple high-transfer experimental analogues with piperazine/pyrimidine/weak-base scaffolds and similar physicochemical liabilities show absolute oral bioavailability of 28–100%, including 46% for brigatinib and 57–77% for the GSK1322322 scaffold. The physicochemical low-bioavailability prior is overridden by this consistent experimental evidence; low-F records (vinpocetine, TFMPP) have zero transferability and are not informative.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule itself; prediction relies on high-transfer analogues.",
    "The query has a very low neutral fraction and high TPSA/HBA, but experimental analogue data override the physicochemical prior; no direct permeability/efflux data for the query are available.",
    "Some high-transfer records come from different therapeutic classes, formulations (e.g., ER), or disease states, adding minor uncertainty."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

